contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // params: depositAmount to deposit (may be zero), and a flag whether to attempt the first withdraw
    function run(uint depositAmount, bool doFirstWithdraw) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount) + (0)); require(depositAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= depositAmount);

        // Snapshot before any action
        uint beforeC = address(c).balance;
        uint beforeThis = address(this).balance;

        // Perform deposit (may be zero)
        c.deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;

        // Snapshot after deposit
        uint afterDepositC = address(c).balance;
        uint afterDepositThis = address(this).balance;

        // Attempt first withdrawAll() if requested; catch revert
        bool firstReverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            firstReverted = true;
        } else {
            firstReverted = false;
        }
        uint afterFirstC = address(c).balance;
        uint afterFirstThis = address(this).balance;

        // Probe: deposit 0 then attempt withdrawAll() to observe remaining recorded credit
        c.deposit{value: 0}(); if (__ESBMC_reverted()) return;
        uint probeBeforeC = address(c).balance;
        uint probeBeforeThis = address(this).balance;

        bool probeReverted;
        c.withdrawAll(); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            probeReverted = true;
        } else {
            probeReverted = false;
        }
        uint probeAfterC = address(c).balance;
        uint probeAfterThis = address(this).balance;

        // Assert the general rule:
        // - If the first withdraw was attempted and succeeded (doFirstWithdraw==true && firstReverted==false), then the probe withdraw must transfer no Ether (probeAfterC == probeBeforeC and probeAfterThis == probeBeforeThis).
        // - If the first withdraw was attempted and reverted (doFirstWithdraw==true && firstReverted==true), then C's balance is unchanged from after the deposit (afterFirstC == afterDepositC).
        // - If the first withdraw was not attempted (doFirstWithdraw==false), treat as no first withdraw: then the probe may behave freely, so no constraint beyond reaching the assert.
        assert(
            (doFirstWithdraw == true && firstReverted == false) ? (probeAfterC == probeBeforeC && probeAfterThis == probeBeforeThis) :
            (doFirstWithdraw == true && firstReverted == true) ? (afterFirstC == afterDepositC) :
            true
        );
    }

    receive() external payable {}
}

