// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ReentrancyDAO c;

    function setUp() public {
        c = new ReentrancyDAO();
    }

    function _run(uint256 depositAmount, bool doFirstWithdraw) internal {
        depositAmount = bound(depositAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP + VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= depositAmount);
        uint beforeC = address(c).balance;
        uint beforeThis = address(this).balance;
        try c.deposit{value: depositAmount}() {} catch { return; }
        uint afterDepositC = address(c).balance;
        uint afterDepositThis = address(this).balance;
        bool firstReverted;
        try c.withdrawAll() {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }
        uint afterFirstC = address(c).balance;
        uint afterFirstThis = address(this).balance;
        try c.deposit{value: 0}() {} catch { return; }
        uint probeBeforeC = address(c).balance;
        uint probeBeforeThis = address(this).balance;
        bool probeReverted;
        try c.withdrawAll() {
            probeReverted = false;
        } catch {
            probeReverted = true;
        }
        uint probeAfterC = address(c).balance;
        uint probeAfterThis = address(this).balance;
        assertTrue((doFirstWithdraw == true && firstReverted == false) ? (probeAfterC == probeBeforeC && probeAfterThis == probeBeforeThis) :
            (doFirstWithdraw == true && firstReverted == true) ? (afterFirstC == afterDepositC) :
            true);
    }

    function testFuzz_run(uint256 depositAmount, bool doFirstWithdraw) public {
        _run(depositAmount, doFirstWithdraw);
    }

    receive() external payable {}
}
